import pandas as pd
import json
import numpy as np
COLUMNS = ['email', 'list']
def task_func(json_file):
    try:
        with open(json_file, 'r') as f:
            data = json.load(f)
    except (FileNotFoundError, json.JSONDecodeError):
        return pd.DataFrame(columns=['email', 'list', 'sum', 'mean']), None
    if not data:
        return pd.DataFrame(columns=['email', 'list', 'sum', 'mean']), None
    records = []
    for item in data:
        email = item.get('email', '')
        lst = item.get('list', [])
        if not isinstance(lst, list):
            lst = []
        records.append({
            'email': email,
            'list': lst,
            'sum': np.sum(lst),
            'mean': np.mean(lst) if len(lst) > 0 else np.nan
        })
    df = pd.DataFrame(records)
    if df.empty:
        return df, None
    ax = df[['sum', 'mean']].plot(kind='bar')
    ax.set_xticklabels(df['email'])
    return df, ax

